/// Work item for the tape-based iterative term builder.
#[allow(dead_code)]
enum BuildTask {
    /// Build a Num term at the given depth, storing result in the given slot.
    BuildNum { depth: u32, slot: usize },
    /// Build a Pred term at the given depth, storing result in the given slot.
    BuildPred { depth: u32, slot: usize },
    /// Build a Expr term at the given depth, storing result in the given slot.
    BuildExpr { depth: u32, slot: usize },
}

/// Helper to consume bytes from the tape.
#[allow(dead_code)]
struct TapeReader<'a> {
    tape: &'a [u8],
    pos: usize,
}

#[allow(dead_code)]
impl<'a> TapeReader<'a> {
    fn new(tape: &'a [u8]) -> Self {
        TapeReader { tape, pos: 0 }
    }

    /// Read the next byte, wrapping around if the tape is exhausted.
    fn next_byte(&mut self) -> u8 {
        if self.tape.is_empty() {
            return 0;
        }
        let b = self.tape[self.pos % self.tape.len()];
        self.pos += 1;
        b
    }

    /// Read a u32 from 4 bytes (little-endian), wrapping tape as needed.
    fn next_u32(&mut self) -> u32 {
        let b0 = self.next_byte() as u32;
        let b1 = self.next_byte() as u32;
        let b2 = self.next_byte() as u32;
        let b3 = self.next_byte() as u32;
        b0 | (b1 << 8) | (b2 << 16) | (b3 << 24)
    }

    /// Read an i32 from tape bytes.
    ///
    /// Returns the full i32 range. Overflow in `![a + b]` native eval paths is
    /// handled by the `SafeArith` trait and the `rust_code_rewrite` pass in the
    /// `language!` macro: arithmetic operators are rewritten to `safe_add`,
    /// `safe_mul`, etc., which return `Option<T>` on overflow rather than
    /// panicking. This removes the need for a restricted range here.
    fn next_i32(&mut self) -> i32 {
        self.next_u32() as i32
    }

    /// Read an i64 from tape bytes.
    fn next_i64(&mut self) -> i64 {
        let lo = self.next_u32() as i64;
        let hi = self.next_u32() as i64;
        lo | (hi << 32)
    }

    /// Read an f64 from tape bytes.
    fn next_f64(&mut self) -> f64 {
        let bits = self.next_i64() as u64;
        let val = f64::from_bits(bits);
        // Avoid NaN/Inf which cause issues with Eq/Ord
        if val.is_nan() || val.is_infinite() { 0.0 } else { val }
    }

    /// Read an f32 from tape bytes.
    fn next_f32(&mut self) -> f32 {
        let bits = self.next_u32();
        let val = f32::from_bits(bits);
        if val.is_nan() || val.is_infinite() { 0.0f32 } else { val }
    }

    /// Read a bool from tape.
    fn next_bool(&mut self) -> bool {
        self.next_byte() & 1 == 1
    }

    /// Read a short string from tape.
    fn next_string(&mut self) -> String {
        let len = (self.next_byte() % 8) as usize;
        (0..len)
            .map(|_| {
                let b = self.next_byte();
                // Map to printable ASCII range 'a'-'z'
                (b'a' + (b % 26)) as char
            })
            .collect()
    }
}

/// Build a `Num` term from an instruction tape.
///
/// Consumes bytes from the tape to choose constructors.
/// At depth 0, only leaf constructors (nullary, literal, var) are chosen.
/// At depth > 0, recursive constructors are also available.
#[allow(dead_code, unused_variables, clippy::let_and_return)]
fn build_num_from_tape(reader: &mut TapeReader<'_>, depth: u32) -> Num {
    if depth == 0 {
        let choice = (reader.next_byte() as usize) % 2;
        let result = match choice {
            0 => {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapNum(Num::NVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
},
            _ => AnyTerm::WrapNum(Num::NumLit((reader.next_i32().unsigned_abs() as i32) & i32::MAX)),
        };
        return result.unwrap_num();
    }

    let choice = (reader.next_byte() as usize) % 7;
    let child_depth = depth - 1;
    match choice {
        0 => {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapNum(Num::NVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
}.unwrap_num(),
        1 => AnyTerm::WrapNum(Num::NumLit((reader.next_i32().unsigned_abs() as i32) & i32::MAX)).unwrap_num(),
        2 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            let f1 = Box::new(build_num_from_tape(reader, child_depth));
            Num::AddNum(f0, f1)
        },
        3 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            let f1 = Box::new(build_num_from_tape(reader, child_depth));
            Num::MulNum(f0, f1)
        },
        4 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            Num::NegNum(f0)
        },
        5 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            Num::FactNum(f0)
        },
        _ => {
            let f0 = Box::new(build_expr_from_tape(reader, child_depth));
            Num::ExprToNum(f0)
        },
    }
}

/// Build a `Pred` term from an instruction tape.
///
/// Consumes bytes from the tape to choose constructors.
/// At depth 0, only leaf constructors (nullary, literal, var) are chosen.
/// At depth > 0, recursive constructors are also available.
#[allow(dead_code, unused_variables, clippy::let_and_return)]
fn build_pred_from_tape(reader: &mut TapeReader<'_>, depth: u32) -> Pred {
    if depth == 0 {
        let choice = (reader.next_byte() as usize) % 2;
        let result = match choice {
            0 => {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapPred(Pred::PVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
},
            _ => AnyTerm::WrapPred(Pred::BoolLit(reader.next_bool())),
        };
        return result.unwrap_pred();
    }

    let choice = (reader.next_byte() as usize) % 5;
    let child_depth = depth - 1;
    match choice {
        0 => {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapPred(Pred::PVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
}.unwrap_pred(),
        1 => AnyTerm::WrapPred(Pred::BoolLit(reader.next_bool())).unwrap_pred(),
        2 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            let f1 = Box::new(build_num_from_tape(reader, child_depth));
            Pred::EqNum(f0, f1)
        },
        3 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            let f1 = Box::new(build_num_from_tape(reader, child_depth));
            Pred::NeNum(f0, f1)
        },
        _ => {
            let f0 = Box::new(build_pred_from_tape(reader, child_depth));
            let f1 = Box::new(build_pred_from_tape(reader, child_depth));
            Pred::AndPred(f0, f1)
        },
    }
}

/// Build a `Expr` term from an instruction tape.
///
/// Consumes bytes from the tape to choose constructors.
/// At depth 0, only leaf constructors (nullary, literal, var) are chosen.
/// At depth > 0, recursive constructors are also available.
#[allow(dead_code, unused_variables, clippy::let_and_return)]
fn build_expr_from_tape(reader: &mut TapeReader<'_>, depth: u32) -> Expr {
    if depth == 0 {
        let result = {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapExpr(Expr::EVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
};
        return result.unwrap_expr();
    }

    let choice = (reader.next_byte() as usize) % 4;
    let child_depth = depth - 1;
    match choice {
        0 => {
    let var_names = ["a", "b", "c", "x", "y", "z"];
    let idx = (reader.next_byte() as usize) % var_names.len();
    AnyTerm::WrapExpr(Expr::EVar(
        mettail_runtime::OrdVar(
            mettail_runtime::Var::Free(
                mettail_runtime::get_or_create_var(var_names[idx])
            )
        )
    ))
}.unwrap_expr(),
        1 => {
            let f0 = Box::new(build_num_from_tape(reader, child_depth));
            Expr::CastNum(f0)
        },
        2 => {
            let f0 = Box::new(build_pred_from_tape(reader, child_depth));
            Expr::CastPred(f0)
        },
        _ => {
            let f0 = Box::new(build_expr_from_tape(reader, child_depth));
            let f1 = Box::new(build_expr_from_tape(reader, child_depth));
            Expr::EPar(f0, f1)
        },
    }
}

/// Generate an arbitrary `Num` term with bounded depth.
///
/// Uses a flat `Vec<u8>` tape interpreted by `build_num_from_tape`.
/// Proptest shrinking produces shorter tapes = simpler terms.
#[allow(dead_code)]
fn arb_num(max_depth: u32) -> BoxedStrategy<Num> {
    // Tape size scales with depth: deeper terms need more bytes
    let max_tape = (10 * (max_depth as usize + 1)).max(20);
    proptest::collection::vec(any::<u8>(), 1..max_tape)
        .prop_map(move |tape| {
            let mut reader = TapeReader::new(&tape);
            build_num_from_tape(&mut reader, max_depth)
        })
        .boxed()
}

